{
  "name": "2023A 射频信号发生器",
  "name_en": "2023A RF Signal Generator",
  "manufacturer": "Aeroflex Test Solutions",
  "description": "这是一台台式射频信号发生器，可在 9 千赫至 1.2 吉赫范围内输出可调的连续波射频信号，并支持频率、幅度、相位、输出开关和频率基准等设置。它常用于射频电路、接收机、通信设备和通用电子测试中的信号注入、校准与性能验证。",
  "description_en": "This is a benchtop RF signal generator that produces adjustable continuous-wave RF signals from 9 kHz to 1.2 GHz, with control of frequency, amplitude, phase, output enable, and frequency reference selection. It is commonly used for signal injection, calibration, and performance verification of RF circuits, receivers, communication equipment, and general electronic test setups.",
  "actions": [
    {
      "action_name": "auto-clear_status_async",
      "description": "异步清除状态和事件寄存器。",
      "description_en": "Asynchronously clear the status and event registers."
    },
    {
      "action_name": "auto-expose_async",
      "description": "异步执行定时信号输出。",
      "description_en": "Asynchronously perform timed signal output."
    },
    {
      "action_name": "auto-local_lockout",
      "description": "设置本地面板锁定状态。",
      "description_en": "Set the local panel lockout state."
    },
    {
      "action_name": "auto-remote",
      "description": "设置远程控制模式。",
      "description_en": "Set the remote control mode."
    },
    {
      "action_name": "auto-reset_async",
      "description": "异步将仪器复位到出厂默认上电状态。",
      "description_en": "Asynchronously reset the instrument to the factory default power-up state."
    },
    {
      "action_name": "auto-self_test_async",
      "description": "异步执行接口和处理器自检。",
      "description_en": "Asynchronously run the interface and processor self-test."
    },
    {
      "action_name": "auto-software_handshake",
      "description": "设置软件握手模式。",
      "description_en": "Set the software handshake mode."
    },
    {
      "action_name": "auto-trigger_async",
      "description": "异步发送触发。",
      "description_en": "Asynchronously send a trigger."
    },
    {
      "action_name": "auto-wait_async",
      "description": "异步等待前序操作完成。",
      "description_en": "Asynchronously wait for the previous operation to complete."
    },
    {
      "action_name": "auto-idn",
      "description": "获取设备标识。",
      "description_en": "Get the instrument identification."
    },
    {
      "action_name": "auto-fitted_options",
      "description": "获取已安装选件。",
      "description_en": "Get the fitted options."
    },
    {
      "action_name": "auto-reset",
      "description": "将仪器复位到出厂默认上电状态。",
      "description_en": "Reset the instrument to the factory default power-up state."
    },
    {
      "action_name": "auto-self_test",
      "description": "执行接口和处理器自检。",
      "description_en": "Run the interface and processor self-test."
    },
    {
      "action_name": "auto-wait",
      "description": "等待前序操作完成。",
      "description_en": "Wait for the previous operation to complete."
    },
    {
      "action_name": "auto-trigger",
      "description": "发送触发。",
      "description_en": "Send a trigger."
    },
    {
      "action_name": "auto-status_byte",
      "description": "获取状态字节。",
      "description_en": "Get the status byte."
    },
    {
      "action_name": "auto-service_request_enabled",
      "description": "获取/设置服务请求使能寄存器。",
      "description_en": "Get/set the service request enable register."
    },
    {
      "action_name": "auto-event_status_reg",
      "description": "获取/设置事件状态寄存器。",
      "description_en": "Get/set the event status register."
    },
    {
      "action_name": "auto-event_status_enabled",
      "description": "获取/设置标准事件使能寄存器。",
      "description_en": "Get/set the standard event enable register."
    },
    {
      "action_name": "auto-clear_status",
      "description": "清除状态和事件寄存器。",
      "description_en": "Clear the status and event registers."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置载波频率。",
      "description_en": "Get/set the carrier frequency."
    },
    {
      "action_name": "auto-amplitude",
      "description": "获取/设置射频幅度。",
      "description_en": "Get/set the RF amplitude."
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置幅度偏置。",
      "description_en": "Get/set the amplitude offset."
    },
    {
      "action_name": "auto-output_enabled",
      "description": "获取/设置射频输出使能状态。",
      "description_en": "Get/set the RF output enable state."
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置载波相位偏移。",
      "description_en": "Get/set the carrier phase offset."
    },
    {
      "action_name": "auto-frequency_standard",
      "description": "获取/设置内部或外部频率基准。",
      "description_en": "Get/set the internal or external frequency standard."
    },
    {
      "action_name": "auto-rflimit",
      "description": "获取/设置射频输出电平上限。",
      "description_en": "Get/set the RF output level limit."
    },
    {
      "action_name": "auto-rflimit_enabled",
      "description": "获取/设置射频输出限幅使能状态。",
      "description_en": "Get/set the RF output limit enable state."
    },
    {
      "action_name": "auto-expose",
      "description": "执行定时信号输出。",
      "description_en": "Perform timed signal output."
    },
    {
      "action_name": "auto-time",
      "description": "获取/设置仪器时间设置。",
      "description_en": "Get/set the instrument time setting."
    }
  ],
  "tag_hints": [
    "RF signal generator",
    "9 kHz to 1.2 GHz",
    "CW signal source",
    "frequency and amplitude control",
    "phase adjustment",
    "receiver testing",
    "communication equipment calibration"
  ]
}

